# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"
require "webmock/rspec"

RSpec.describe RelayJob do
  it "RelayJob posts rows inserted out of position order in ascending outbox_position and leaves them unsent on a 503" do
    stamp = Time.utc(2026, 3, 2, 9)
    [30, 10, 20].each do |position|
      OutboxSnapshot.create!(
        "outbox_position" => position, "id" => 900 + position, "project_id" => 3, "user_id" => 4, "agent_id" => nil,
        "work_date" => Date.new(2026, 3, 2), "duration" => 60.0, "note" => nil, "bill_status" => "unbilled",
        "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
        "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => stamp, "updated_at" => stamp, "company_id" => 1, "version" => 1,
        "generation" => 1
      )
    end
    posted_positions = []
    stub_request(:post, %r{\Ahttp://monolith\.relay-job\.test}).to_return do |request|
      posted_positions.concat(JSON.parse(request.body).fetch("snapshots").map { |item| item.fetch("outbox_position") })
      { status: 503, body: "" }
    end

    with_timekeeping_env(
      Timekeeping::Environment::MONOLITH_SNAPSHOT_URL => "http://monolith.relay-job.test",
      Timekeeping::Environment::SERVICE_TOKEN => "relay-job-spec-service-token"
    ) { described_class.perform_now }

    # "It delivers in `outbox_position` order."
    expect(posted_positions).to eq([10, 20, 30])
    # "The relay marks a row sent only after a `200`, so delivery is at least once."
    expect(OutboxSnapshot.where(sent_at: nil).count).to eq(3)
  end
end
